// Mismas fechas que bq_refresh.ps1, en hora local del worker.
// Cada nodo de BigQuery las consume por expresion: {{ $('Fechas').first().json.D.HIST }}
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const fmt = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const Y = now.getFullYear(), M = now.getMonth(), DD = now.getDate();

const prevLast = new Date(Y, M, 0).getDate();
const pdDay    = Math.max(1, Math.min(DD - 1, prevLast));
const dow      = now.getDay();
const dtm      = dow === 0 ? 6 : dow - 1;

const D = {
  HIST: '2025-01-01', DEEP: '2024-01-01', ENIGMA: '2026-04-01',
  YEST: fmt(new Date(Y, M, DD - 1)),
  CUR:  fmt(new Date(Y, M, 1)),
  PREV: fmt(new Date(Y, M - 1, 1)),
  M2:   fmt(new Date(Y, M - 2, 1)),
  M3:   fmt(new Date(Y, M - 3, 1)),
  M4:   fmt(new Date(Y, M - 4, 1)),
  M5:   fmt(new Date(Y, M - 5, 1)),
  M6:   fmt(new Date(Y, M - 6, 1)),
  M7:   fmt(new Date(Y, M - 7, 1)),
  PREV_DAY: fmt(new Date(Y, M - 1, pdDay)),
  DAY_OF_MONTH: String(DD - 1),
  W8:   fmt(new Date(Y, M, DD - dtm - 84)),
};
return [{ json: { D } }];

const KEYS = ["behaviour", "beh_mtd", "beh_pacing", "qr_rolling", "registrations", "reg_mtd", "reg_pacing", "landing_traffic", "landing_pacing", "spend_pom", "nmv_monthly", "nmv_lt_by_status", "nmv_weekly", "nmv_mtd", "nmv_pacing", "data_freshness", "act1", "act2", "act_source", "act_new_days", "churn", "churn_comp", "churn_mtd", "earnings_buckets", "retention_by_segment", "retention_cohort_curve", "link_gen_monthly", "link_gen_daily", "link_gen_mtd_comp", "link_gen_by_segment", "link_gen_earnings_by_status", "mkt_context"];
const data = {}, vacias = [];
for (const k of KEYS) {
  let rows = [];
  try { rows = $('agg_' + k).first().json.data || []; } catch (e) { rows = []; }
  data[k] = rows;
  if (!rows.length) vacias.push(k);
}
// Un token vencido hace que TODAS vuelvan vacias. Sin este guard se publica un
// snapshot de 32 arrays vacios encima del bueno.
if (vacias.length >= KEYS.length / 2) {
  throw new Error('ABORTADO: ' + vacias.length + '/' + KEYS.length +
                  ' queries vacias. No se escribe el Sheet. Vacias: ' + vacias.join(', '));
}
const now = new Date();
const snapshotJson = JSON.stringify({
  savedAt: now.toISOString(),
  savedAtDisplay: now.toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' }),
  data,
});
return [{ json: { snapshotJson, kb: Math.round(snapshotJson.length/1024), vacias,
                  filas: Object.fromEntries(KEYS.map(k => [k, data[k].length])) } }];

// Una celda de Sheets aguanta 50.000 caracteres; cortamos en 40.000 por margen.
const CHUNK = 40000;
const SENTINELA = '~';  // sin esto, un pedazo que arranque con = o + lo toma como formula
const json = $('Armar snapshot').first().json.snapshotJson;

const items = [];
for (let i = 0; i < json.length; i += CHUNK) {
  items.push({ json: { snapshot: SENTINELA + json.slice(i, i + CHUNK) } });
}
if (!items.length) throw new Error('snapshot vacio, no hay nada para escribir');
return items;

